def maxFixedPoints(nums):
    # An element at index i with value v can become fixed only if i - v >= 0,
    # meaning exactly i - v elements before it get deleted
    candidates = []
    for i, v in enumerate(nums):
        if v <= i:
            candidates.append((i - v, v))

    # Chosen elements need non-decreasing (i - v): sort by it, ties by value
    candidates.sort()

    # Chosen elements also need strictly increasing values:
    # find the longest strictly increasing subsequence with patience sorting
    tails = []  # tails[len-1] = smallest possible tail of an increasing chain of that length
    for _, v in candidates:
        # Binary search for the first tail >= v (strictness)
        lo, hi = 0, len(tails)
        while lo < hi:
            mid = (lo + hi) // 2
            if tails[mid] < v:
                lo = mid + 1
            else:
                hi = mid
        if lo == len(tails):
            tails.append(v)
        else:
            tails[lo] = v

    # Length of the longest chain is the maximum number of fixed points
    return len(tails)
